/* open the settings screen and show one table through the real walker and the real shims */
static int show(const FrontendScreen *s, FssVis *v)
{
    int h = gw_Ui_SetOpen(0, 0, "MAIN MENU", "", "SETTINGS");
    if (h < 0) return h;
    gw_Ui_SetTabs(h, 6, "VIDEO,AUDIO,CONTROLS,ONLINE,GAME,MODS", 0);
    fss_visible(s, v); fss_table_submit(h, s, v);
    return h;
}
static void resubmit(int h, const FrontendScreen *s, FssVis *v) { fss_visible(s, v); fss_table_submit(h, s, v); }
static AtRect hit_row(const AtHits *hits, int i)
{
    int k;
    AtRect none = { 0, 0, 0, 0 };
    for (k = 0; k < hits->n; k++) if (hits->h[k].kind == AT_HIT_CELL && hits->h[k].b == i) return hits->h[k].r;
    return none;
}
/* every recorded text that sits on a row lies inside that row, measured with the width that drew it */
static int texts_in_rows(const AtHits *hits)
{
    int i, k;
    for (i = 0; i < REC.nt; i++) for (k = 0; k < hits->n; k++) {
        const AtRect *r;
        if (hits->h[k].kind != AT_HIT_CELL) continue;
        r = &hits->h[k].r;
        if (REC.t[i].base > r->y + 2.0f && REC.t[i].base < r->y + r->h && text_right(&REC.t[i]) > r->x && text_left(&REC.t[i]) < r->x + r->w)
            if (text_left(&REC.t[i]) < r->x - 0.01f || text_right(&REC.t[i]) > r->x + r->w + 0.01f) { printf("  text \"%s\" leaves its row\n", REC.t[i].s); return i; }
    }
    return -1;
}
static void render_screen(int h, float w, AtHits *hits)
{
    AtSink s = rec_sink();
    at_render(&slot_of(h)->sc, &slot_of(h)->view, w, 10000.0, 1, &FAKE, &s, hits);
}

