{
    CHECK(ntables() == 9);
    CHECK(tbl("fe_items_set_video")->n == 6 && tbl("fe_items_set_audio")->n == 3 && tbl("fe_items_set_controls")->n == 12);
    CHECK(tbl("fe_items_set_online")->n == 6 && tbl("fe_items_set_gameplay")->n == 10 && tbl("fe_items_remap")->n == 20 && tbl("fe_items_howto_online")->n == 6);
    CHECK(tbl("fe_items_vs_setup")->n == 10 && tbl("fe_items_online")->n == 9);
}

/* per page, at 640 and 853, with every row enabled and then every enabled predicate failing: the style checks on every row kind the page contains */
static void every_row_is_drawable(void)
{
    static AtHits hits;
    int t, w, en, i;
    for (t = 0; t < ntables(); t++) for (w = 0; w < 2; w++) for (en = 0; en < 2; en++) {
        const StubTable *T = &all_tables[t];
        FrontendScreen scr; FssVis v; int h;
        AtRect canvas; float cw = w ? 853.3333f : 640.0f;
        canvas.x = 0.0f; canvas.y = 0.0f; canvas.w = cw; canvas.h = 480.0f;
        scr.title = "SETTINGS"; scr.subtitle = T->name; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
        reset_set(); g_gen = en;
        h = show(&scr, &v);
        CHECK(h >= 0 && v.n == T->n);
        for (i = 0; i < v.n; i++) {                                       /* each row in turn: drawn at rest, then focused with its three cues */
            AtRect row, area;
            StySig rest, foc;
            int other = i == 0 ? 1 : 0, scroll;
            slot_of(h)->view.focus.index = i; gs_ui_fix_scroll(slot_of(h)); scroll = slot_of(h)->view.scroll;   /* the window that holds row i */
            slot_of(h)->view.focus.index = other; slot_of(h)->view.scroll = scroll;                             /* the focus is elsewhere: row i is at rest */
            render_screen(h, cw, &hits);
            row = hit_row(&hits, i);
            CHECK(row.w > 0.0f);
            area.x = row.x - 4.0f; area.y = row.y - 4.0f; area.w = row.w + 8.0f; area.h = row.h + 8.0f;
            rest = sty_sig_in(0, area);
            CHECK(corners_clear(row, (float) AT_PX_CH_S));
            CHECK(texts_legible());
            CHECK(sty_text_inside(canvas, 0) == -1);                        /* nothing leaves the canvas */
            CHECK(texts_in_rows(&hits) == -1);                              /* nothing runs out of its row: a label, a value and a reason fit or are cut */
            slot_of(h)->view.focus.index = i; slot_of(h)->view.scroll = scroll;
            render_screen(h, cw, &hits);
            foc = sty_sig_in(0, area);
            CHECK(sty_focus_cues(rest, foc) == 3);                          /* lift, ember edge and tick on every kind the page has */
        }
        gw_Ui_SetClose(h);
    }
}

/* Review Focus 2: min, max, step and wrap per row, through the same rule the walker uses, with the real ranges */
static void round_trips(void)
{
    int t, i;
    for (t = 0; t < ntables(); t++) {
        const StubTable *T = &all_tables[t];
        FrontendScreen scr; FssVis v;
        scr.title = "T"; scr.subtitle = "S"; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
        g_gvis = 1; g_gen = 1;
        fss_visible(&scr, &v);
        CHECK(v.n == T->n);
        for (i = 0; i < T->n; i++) {
            const FrontendItem *it = &T->rows[i];
            unsigned fx;
            CHECK(it->help != NULL && it->help[0] != '\0');                  /* every row explains itself (the explainer's WHAT) */
            CHECK(it->label != NULL && it->label[0] != '\0');
            if (it->kind == FE_SLIDER && it->set != NULL) {
                CHECK(it->max > it->min);                                    /* a settable slider has a range */
                g_gv = it->max; g_gsets = 0; fx = fss_table_event(&scr, &v, i, FSS_EV_CHANGE, +1);
                CHECK(g_gsets == 0 && (fx & FSS_FX_BUMP));                   /* held at the top: nothing set, the kit's bump */
                g_gv = it->min; g_gsets = 0; fx = fss_table_event(&scr, &v, i, FSS_EV_CHANGE, +1);
                CHECK(g_gsets == 1 && g_glast > it->min && g_glast <= it->min + (it->step > 0 ? it->step : 1) && (fx & FSS_FX_MOVE));
                g_gv = it->min; g_gsets = 0; fx = fss_table_event(&scr, &v, i, FSS_EV_CHANGE, -1);
                CHECK(g_gsets == 0 && (fx & FSS_FX_BUMP));                   /* and at the bottom */
            }
            if (it->kind == FE_CHOICE) {
                int n = it->max - it->min + 1;
                CHECK(T->nopts[i] == 0 || T->nopts[i] == n);                 /* the option strings cover the range */
                g_gv = it->max; g_gsets = 0; fss_table_event(&scr, &v, i, FSS_EV_CHANGE, +1);
                CHECK(g_gsets == 1 && g_glast == it->min);                   /* a choice wraps at the top ... */
                g_gv = it->min; g_gsets = 0; fss_table_event(&scr, &v, i, FSS_EV_CHANGE, -1);
                CHECK(g_gsets == 1 && g_glast == it->max);                   /* ... and at the bottom */
            }
            if (it->kind == FE_TOGGLE) {
                g_gv = 0; fss_table_event(&scr, &v, i, FSS_EV_CHANGE, +1); CHECK(g_glast == 1);
                g_gv = 1; fss_table_event(&scr, &v, i, FSS_EV_CHANGE, -1); CHECK(g_glast == 0);
            }
        }
    }
}

static void options_the_host_shows(void)
{
    const StubTable *T = tbl("fe_items_set_video");
    FrontendScreen scr; FssVis v; int h;
    AtItem *it;
    scr.title = "T"; scr.subtitle = "S"; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
    reset_set(); g_gv = 1;
    h = show(&scr, &v);
    it = &slot_of(h)->sc.items[1];                                          /* Render Scale: six options */
    CHECK(it->vkind == AT_VAL_CHOICE && it->n_opts == 6 && strcmp(it->text, "1x") == 0 && strcmp(it->opt[5], "4x") == 0);
    g_gv = 0; resubmit(h, &scr, &v); CHECK(strcmp(slot_of(h)->sc.items[1].text, "Auto (window)") == 0);   /* the text follows the value, every frame */
    gw_Ui_SetClose(h);
    /* the remap page's Game Input has 22 options: more than the record holds, so the walker shows the text */
    T = tbl("fe_items_remap");
    scr.items = T->rows; scr.n_items = T->n;
    reset_set(); g_gv = 3;
    h = show(&scr, &v);
    it = &slot_of(h)->sc.items[2];
    CHECK(it->vkind == AT_VAL_CHOICE && it->n_opts == 0 && strcmp(it->text, "Y") == 0);                  /* option 3 of fcr_targets */
    g_gv = 21; resubmit(h, &scr, &v); CHECK(strcmp(slot_of(h)->sc.items[2].text, "Analog R") == 0);
    gw_Ui_SetClose(h);
}

static void disabled_rows_say_why(void)
{
    static AtHits hits;
    const StubTable *T = tbl("fe_items_remap");
    FrontendScreen scr; FssVis v; int h, i, why = 0;
    scr.title = "T"; scr.subtitle = "S"; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
    reset_set(); g_gen = 0;
    h = show(&scr, &v);
    for (i = 0; i < v.n; i++) {
        const AtItem *it = &slot_of(h)->sc.items[i];
        if (it->flags & AT_CELL_DISABLED) { why++; CHECK(strcmp(it->reason, "Connect a controller to this port first.") == 0); }
    }
    CHECK(why == 5);                                                         /* Bind Input, New, Rename, Delete Profile, Reset to Default */
    render_screen(h, 640.0f, &hits);
    CHECK(find_text("Connect a controller to this port first.") != NULL && texts_legible());   /* said in words, not only dimmed */
    gw_Ui_SetClose(h);
    reset_set(); g_gen = 1;
    h = show(&scr, &v);
    for (i = 0; i < v.n; i++) CHECK(!(slot_of(h)->sc.items[i].flags & AT_CELL_DISABLED));
    gw_Ui_SetClose(h);
}

/* Review Focus 5: the Stick Dead Zone row (fsc_any_sdl) shows and hides; focus follows by id */
static void visible_rows_change(void)
{
    const StubTable *T = tbl("fe_items_set_controls");
    FrontendScreen scr; FssVis v; int h;
    scr.title = "T"; scr.subtitle = "S"; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
    reset_set(); g_gvis = 1;
    h = show(&scr, &v);
    CHECK(slot_of(h)->sc.n_items == 12 && strcmp(slot_of(h)->sc.items[6].id, "i6") == 0 && strcmp(slot_of(h)->sc.items[6].label, "Stick Dead Zone") == 0);
    gw_Ui_SetFocus(h, "i6");
    g_gvis = 0; resubmit(h, &scr, &v);
    CHECK(slot_of(h)->sc.n_items == 11 && strcmp(focused_id(h), "i7") == 0);   /* the next visible row, never nothing */
    g_gvis = 1; resubmit(h, &scr, &v);
    CHECK(slot_of(h)->sc.n_items == 12 && strcmp(focused_id(h), "i7") == 0);   /* and when it comes back the focus stays where it is */
    gw_Ui_SetFocus(h, "i11"); g_gvis = 0; resubmit(h, &scr, &v);
    CHECK(strcmp(focused_id(h), "i11") == 0);                                  /* a row after the hidden one keeps its id */
    gw_Ui_SetClose(h);
}

static void mods_41_rows_and_help(void)                                  /* Review Focus 9 */
{
    static FrontendItem M[41];
    static char help[41][520];
    static AtHits hits;
    FrontendScreen scr; FssVis v; int h, i, seen = 0, found = 0;
    AtLayout L;
    memset(M, 0, sizeof M);
    M[0].kind = FE_SLIDER; M[0].label = "Mods"; M[0].help = "Turn mods on or off."; M[0].get = gen_get; M[0].format = gen_fmt;
    for (i = 1; i < 41; i++) {
        memset(help[i], 'x', 511); help[i][511] = '\0';                       /* a 511-character mod help line (FE_HELP_STR) */
        M[i].kind = FE_TOGGLE; M[i].label = "A Mod With A Name"; M[i].help = help[i]; M[i].get = gen_get; M[i].set = gen_set; M[i].max = 1; M[i].step = 1;
    }
    scr.title = "SETTINGS"; scr.subtitle = "MODS"; scr.items = M; scr.n_items = 41; scr.art = 0;
    reset_set();
    h = show(&scr, &v);
    CHECK(v.n == 41 && slot_of(h)->sc.n_items == 41);                         /* 41 rows fit the record */
    gw_Ui_SetFocus(h, "i40"); gw_Ui_SetExplain(h, NULL, NULL, NULL, NULL, "");
    CHECK(strlen(slot_of(h)->view.ex.what) <= AT_TEXT - 1 && strstr(slot_of(h)->view.ex.what, "...") != NULL);   /* help_clamped: an ellipsis, not an overflow */
    render_screen(h, 640.0f, &hits);
    at_layout(640.0f, AT_PRESET_NORMAL, &L);
    CHECK(texts_legible());
    for (i = 0; i < REC.nt; i++) if (strncmp(REC.t[i].s, "xxx", 3) == 0) {
        CHECK(text_left(&REC.t[i]) >= L.explainer.x - 0.01f && text_right(&REC.t[i]) <= L.explainer.x + L.explainer.w + 0.01f); seen++;
    }
    CHECK(seen >= 1 && seen <= 4);                                            /* wrapped to at most 4 lines, all inside the explainer */
    for (i = 0; i < hits.n; i++) if (hits.h[i].kind == AT_HIT_CELL && hits.h[i].b == 40) found = 1;
    CHECK(found);                                                             /* the 41st row is on screen when it has the focus */
    gw_Ui_SetClose(h);
}

static void explainer_from_the_row(void)
{
    const StubTable *T = tbl("fe_items_set_audio");
    FrontendScreen scr; FssVis v; int h;
    const AtExplainer *e;
    scr.title = "T"; scr.subtitle = "S"; scr.items = T->rows; scr.n_items = T->n; scr.art = 0;
    reset_set(); g_gv = 45;
    h = show(&scr, &v);
    gw_Ui_SetFocus(h, "i0"); gw_Ui_SetExplain(h, NULL, NULL, NULL, NULL, "");
    e = &slot_of(h)->view.ex;
    CHECK(strcmp(e->kicker, "VIDEO") == 0);                                   /* the tab strip says VIDEO here: the adapter names the tab, the test only the first */
    CHECK(strcmp(e->title, "Master Volume") == 0 && strcmp(e->what, "Everything the game plays.") == 0 && strcmp(e->now_text, "NOW value 45") == 0);   /* a slider's NOW is the game's own format */
    gw_Ui_SetFocus(h, "i2"); gw_Ui_SetExplain(h, NULL, NULL, NULL, NULL, "");
    CHECK(strcmp(e->title, "Output") == 0 && e->now_text[0] == '\0');         /* value 45 is outside the two options: nothing is claimed */
    g_gv = 1; resubmit(h, &scr, &v); gw_Ui_SetExplain(h, NULL, NULL, NULL, NULL, "");
    CHECK(strcmp(e->now_text, "NOW Mono") == 0);
    CHECK(e->no_well == 1 && e->media_model == AT_NO_MODEL);                  /* no media well: the controller diagram and the render sketch are not built */
    gw_Ui_SetClose(h);
}

